-- Textos del correu al propietari en català, castellà, francès, alemany, neerlandès
-- i anglès, a partir del text anglès del PDF (pàg. 18). Queden marcats «pendent de
-- revisar» fins que una persona de l'oficina els revisa a Configuració → Textos de correu.
alter table public.email_templates add column if not exists reviewed boolean not null default true;

on conflict (kind, language) do nothing;
